import {escapeHtml as esc} from './core.mjs';
import {mountPortalMotion} from './portal-motion.mjs';
export async function api(path,options={}){
 if(globalThis.mentraNative&&path==='logout'){globalThis.mentraNativeCalendar?.cancel();await globalThis.mentraNativePush?.unsubscribe();await globalThis.mentraNativeClearCache?.();}
 const r=await (globalThis.mentraNativeApi?globalThis.mentraNativeApi(path,{...options,headers:{'Content-Type':'application/json',...options.headers}}):fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}}));
 let b;try{b=await r.json();}catch{throw Error('Servidor indisponível.');}
 if(!r.ok)throw Object.assign(Error(b.error||'Falha na operação.'),{status:r.status});
 if(globalThis.mentraNative){if(path==='me'&&b.user?.id)globalThis.mentraNativeUserId=b.user.id;if(path==='logout'){globalThis.mentraNativeUserId=null;globalThis.mentraPlatform=null;}}
 return b;
}
const brl=c=>(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const brlShort=c=>c%100===0?(c/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:0,maximumFractionDigits:0}):brl(c);
export const periodLabel=days=>({30:'mês',90:'trimestre',365:'ano'})[days||30]||`período de ${days} dias`;
export const PROMO_FINE_PRINT='Valor promocional válido somente para o primeiro período contratado (primeiro mês, trimestre ou ano). Após esse período, a renovação é feita pelo valor regular do plano.';
export const formatPlanPrice=p=>p.priceCents===null||p.priceCents===undefined?'Preço em definição':brl(p.priceCents)+' / '+periodLabel(p.days);
// chargeCents comes from the server: what this person would pay now (promotional only before a first payment).
export const planCharge=p=>p.chargeCents??p.priceCents??null;
export function planPriceMarkup(p){
 if(p.priceCents===null||p.priceCents===undefined)return '<p class="plan-price"><strong>Preço em definição</strong></p>';
 const charge=planCharge(p),per=periodLabel(p.days);
 if(charge<p.priceCents)return `<p class="plan-price promo"><span class="plan-price-from">De <s>${brl(p.priceCents)}</s></span> <span class="plan-price-now">por <strong>${brlShort(charge)}</strong></span> <small>no primeiro ${per}</small></p>`;
 return `<p class="plan-price"><strong>${brl(p.priceCents)}</strong> <small>/ ${per}</small></p>`;
}
const finePrint=plans=>plans.some(p=>p.promoPriceCents)?`<p class="plan-fineprint">${PROMO_FINE_PRINT}</p>`:'';
export const subscriptionLabel=status=>({active:'Ativo',pending:'Aguardando ativação',canceled:'Cancelado',expired:'Expirado'})[status]||status;
export const send=(path,data,method='POST',options={})=>api(path,{...options,method,body:JSON.stringify(data)});
function showRecovery(root,code,mode='recover'){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><section class="card"><h1>Guarde seu código de recuperação.</h1><p>Este código permite recuperar sua conta se esquecer a senha. Ele será exibido somente agora. Guarde em um lugar seguro fora deste aparelho e não compartilhe.</p><code id="recovery-code-value" style="display:block;overflow-wrap:anywhere;padding:20px;background:#eef2e9">${esc(code)}</code><p id="recovery-copy-status" role="status" aria-live="polite"></p><div class="button-row" style="display:flex;gap:10px;flex-wrap:wrap;margin:12px 0"><button type="button" class="outline" id="recovery-copy">Copiar código</button><button type="button" class="outline" id="recovery-download">Baixar código (.txt)</button></div><p>Ao recuperar a conta, o código será substituído por um novo.</p><button class="primary" id="recovery-continue">Já guardei. Continuar</button></section></main>`;const status=root.querySelector('#recovery-copy-status');root.querySelector('#recovery-copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);status.textContent='Código copiado. Cole em um gerenciador de senhas ou local seguro.';}catch{status.textContent='Selecione o código acima e copie manualmente.';}};root.querySelector('#recovery-download').onclick=()=>{const url=URL.createObjectURL(new Blob([`Mentra Life — Código pessoal de recuperação\n\n${code}\n\nGuarde em local seguro e não compartilhe.\n`],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mentra-codigo-recuperacao.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Arquivo de recuperação gerado.';};root.querySelector('#recovery-continue').onclick=()=>{if(mode==='recover'){try{sessionStorage.setItem('mentra-auth-notice',JSON.stringify({message:'Conta recuperada. Entre com a nova senha que você definiu.',at:Date.now()}));}catch{}}location.reload();};}
export function recoveryForm(root,returnPath='/'){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><section class="card portal-access"><div><h1>Recupere seu acesso.</h1><p>Use o código entregue ao criar sua conta. Sua senha será substituída e os dispositivos conectados sairão da conta.</p><a href="${returnPath==='/admin'?(globalThis.mentraNative?'/admin.html':'/admin'):'/'}">Voltar ao login</a></div><form id="recovery-form"><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Código de recuperação<input name="recoveryCode" required minlength="64" maxlength="64" autocomplete="off"></label><label>Nova senha<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p role="alert" id="recovery-error"></p><button class="primary" type="submit">Recuperar conta</button></form></section></main>`;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const result=await send('recover',Object.fromEntries(new FormData(e.target)));showRecovery(root,result.recoveryCode);}catch(error){root.querySelector('#recovery-error').textContent=error.message;b.disabled=false;}};}
export async function startPlatform(){
 const root=document.querySelector('#app');let me;try{me=await api('me');}catch(e){if(e.status!==401){root.innerHTML=`<main id="main-content" class="portal" tabindex="-1"><h1>Mentra Life</h1><p>${esc(e.message)}</p><button id="retry-platform">Tentar novamente</button></main>`;root.querySelector('#retry-platform').onclick=()=>location.reload();return null;}}
 if(!me){await portal(root);return null;}
 const saved=await api('state');return {...me,...saved};
}
const FEATURES=[
 ['Rotina com clareza','Agenda, tarefas e prioridades no seu ritmo.','day','<div class="site-row is-done"><i class="site-check"><svg viewBox="0 0 16 16"><path d="M3.5 8.5l3 3 6-7"/></svg></i><span>Pagar a conta de luz</span><time>08:00</time></div><div class="site-row"><i class="site-check"></i><span>Consulta com a dentista</span><time>10:30</time></div><div class="site-row"><i class="site-check"></i><span>Revisar o plano da semana</span><time>16:00</time></div>'],
 ['Dinheiro organizado','Contas, lançamentos, compromissos e relatórios.','money','<div class="site-figure"><small>Saldo do mês</small><b>R$ 1.240,00</b></div><div class="site-bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>'],
 ['Ideias em movimento','Planos editáveis para começar e acompanhar.','plan','<ol><li class="is-done">Ideia anotada</li><li class="is-done">Primeiro passo</li><li class="is-now">Em andamento</li><li>Concluído</li></ol>'],
 ['Documentos à mão','Recibos em PDF e biblioteca de documentos.','docs','<span class="site-paper"><b>Contrato</b><i></i><i></i><i></i></span><span class="site-paper"><b>Exame</b><i></i><i></i><i></i></span><span class="site-paper"><b>Recibo</b><i></i><i></i><i></i><em>PDF</em></span>']
];
const smooth=()=>globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
async function portal(root){
 const {plans,paymentsConfigured}=await api('plans');let mode='login',selected=plans[0].id;
 const accessMarkup=()=>`<div><p class="eyebrow">SEU ESPAÇO</p><h2>${mode==='register'?'Comece com um pouco de clareza.':'Que bom ter você de volta.'}</h2><p>Seus dados ficam associados exclusivamente à sua conta.</p><button class="text-link" id="switch-auth">${mode==='register'?'Já tenho uma conta':'Quero criar uma conta'}</button></div><form id="auth-form">${mode==='register'?'<label>Seu nome<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label>E-mail<input name="email" type="email" autocomplete="email" required></label><label>Senha<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="12" maxlength="128" required>${mode==='register'?'<small>Use pelo menos 12 caracteres.</small>':''}</label>${mode==='register'?`<label>Seu plano<select name="plan">${plans.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}${p.days?` · ${p.days} dias`:''}</option>`).join('')}</select></label>`:''}<p id="auth-error" role="alert"></p><button class="primary" type="submit">${mode==='register'?'Criar minha conta':'Entrar'}</button></form>`;
 root.innerHTML=`<div class="portal site"><header class="portal-nav"><a href="/" class="portal-brand"><img src="assets/mentra-logo-256.webp" width="256" height="256" alt="">mentra <small>LIFE</small></a><nav class="site-links" aria-label="Seções da página"><a href="#recursos">Recursos</a><a href="#planos">Planos</a></nav><a id="open-auth" href="#acesso">Acessar <span>minha conta</span> →</a></header><main id="main-content" tabindex="-1"><section class="portal-hero"><div class="site-wrap site-hero-grid"><div class="site-hero-copy"><p class="eyebrow">UM LUGAR PARA SUA VIDA</p><h1><span class="site-line"><span>Sua vida,</span></span> <span class="site-line"><span><em>mais leve.</em></span></span></h1><p class="site-lede">Organize o dia, cuide do seu dinheiro e transforme ideias em próximos passos. Sua Mentra acompanha você.</p><div class="site-hero-actions"><a class="primary" href="#planos">Encontre seu plano →</a><a class="site-quiet" href="#recursos">Ver o que cabe aqui</a></div></div><div class="site-stage"><span class="site-orbit site-orbit-a" aria-hidden="true"><i></i></span><span class="site-orbit site-orbit-b" aria-hidden="true"><i></i></span><div class="site-face" data-depth="14"><div class="site-face-float"><div class="site-face-in"><img src="assets/mentra-face-hero.webp" width="768" height="768" fetchpriority="high" alt="Mentra, sua assistente pessoal"></div></div></div><div class="site-chip site-chip-day" data-depth="34" aria-hidden="true"><div><small>HOJE</small><b>3 tarefas, 1 compromisso</b></div></div><div class="site-chip site-chip-money" data-depth="-26" aria-hidden="true"><div><small>ESTE MÊS</small><b>R$ 1.240,00</b><span class="site-meter"><i></i></span></div></div></div></div></section><section class="site-manifesto"><div class="site-wrap"><p class="eyebrow">MENOS PESO, MAIS CLAREZA</p><h2 class="site-statement" data-words>A cabeça não foi feita para guardar tudo. A Mentra guarda por você: o dia, o dinheiro, os planos e os papéis da vida em um só lugar, no seu ritmo.</h2></div></section><section class="portal-benefits" id="recursos"><div class="site-wrap"><header class="site-head" data-reveal><p class="eyebrow">O QUE CABE AQUI</p><h2>Quatro frentes da vida, uma só casa.</h2></header><div class="site-bento">${FEATURES.map(([t,d,kind,vignette],i)=>`<article class="site-feature site-feature-${kind}" data-reveal><div class="site-feature-copy"><span class="site-index">0${i+1}</span><h3>${t}</h3><p>${d}</p></div><div class="site-vig" aria-hidden="true">${vignette}</div></article>`).join('')}</div></div></section><section id="planos"><div class="site-wrap"><header class="site-head" data-reveal><p class="eyebrow">ESCOLHA SEU PERÍODO</p><h2>Acesso completo à Mentra, no período que preferir.</h2><p>Um único plano com todos os recursos e a mesma capacidade de IA. Você escolhe por quanto tempo quer liberar o acesso.</p></header><div class="portal-plans">${plans.map((p,i)=>`<article class="card ${i===1?'featured':''}" data-reveal><p class="eyebrow">${p.days?`${p.days} DIAS DE ACESSO`:'MENTRA LIFE'}</p><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p>${storeApp()?'':planPriceMarkup(p)}<ul><li>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA por mês</li><li>Agenda, tarefas e documentos</li><li>Finanças e recibos em PDF</li><li>Impulso e bem-estar</li><li>Painel individual</li></ul><button class="${i===1?'primary':'outline'}" data-plan="${p.id}">Escolher o plano ${esc(p.name)}</button></article>`).join('')}</div>${storeApp()?'':finePrint(plans)}<p class="site-plans-note">${storeApp()?'Crie sua conta para começar. Os recursos do seu plano acompanham a sua conta Mentra.':paymentsConfigured?'Crie uma conta e pague com PIX para ativar seu plano.':'Cadastro disponível. A contratação e a ativação serão liberadas após a configuração dos pagamentos.'}</p></div></section><div class="site-wrap site-access-wrap"><section class="portal-access card" id="acesso" data-reveal></section></div></main><footer><div class="site-wrap"><div class="site-foot-row"><p>Mentra Life · Um passo de cada vez.</p><a href="mailto:contato@mentralife.com.br">Contato e suporte</a></div><div class="site-wordmark" aria-hidden="true" data-reveal>mentra</div></div></footer></div>`;
 const access=root.querySelector('#acesso'),go=target=>target?.scrollIntoView({behavior:smooth(),block:'start'});
 // Only the access card is redrawn when the mode changes: the rest of the page keeps its state and its entrance.
 function renderAccess(animate){
  access.innerHTML=accessMarkup();
  if(animate){access.classList.remove('is-swapping');void access.offsetWidth;access.classList.add('is-swapping');}
  const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='text-link auth-recovery';recoveryButton.textContent='Recuperar acesso com meu código';recoveryButton.onclick=()=>recoveryForm(root);access.querySelector('#auth-form').append(recoveryButton);
  access.querySelector('#switch-auth').onclick=()=>{mode=mode==='register'?'login':'register';renderAccess(true);go(access);};
  access.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const result=await send(mode==='register'?'register':'login',Object.fromEntries(new FormData(e.target)));if(result.recoveryCode){showRecovery(root,result.recoveryCode,mode==='register'?'register':'recover');return;}location.reload();}catch(error){access.querySelector('#auth-error').textContent=error.message;button.disabled=false;}};
 }
 renderAccess(false);
 try{const raw=sessionStorage.getItem('mentra-auth-notice');if(raw){sessionStorage.removeItem('mentra-auth-notice');const note=JSON.parse(raw);if(Date.now()-note.at<120000){const box=root.querySelector('#auth-error');if(box){box.textContent=note.message;box.classList.add('auth-success');box.setAttribute('role','status');}}}}catch{}
 root.querySelector('#open-auth').onclick=e=>{e.preventDefault();if(mode!=='login'){mode='login';renderAccess(true);}go(access);};
 root.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{selected=b.dataset.plan;const changed=mode!=='register';mode='register';renderAccess(changed);if(!changed)access.querySelector('select[name=plan]').value=selected;go(access);});
 // In-page links scroll without touching the hash, which belongs to the app's router.
 root.querySelectorAll('a[href^="#"]:not(#open-auth)').forEach(link=>link.onclick=e=>{const target=root.querySelector(link.getAttribute('href'));if(!target)return;e.preventDefault();go(target);});
 mountPortalMotion(root.querySelector('.site'));
}
export function accountMarkup(platform,preferences=''){return `<div class="page-heading"><div><p class="eyebrow">MEU ESPAÇO</p><h1>Seu jeito de seguir em frente.</h1><p class="subtitle">${esc(platform.user.name)} · ${esc(platform.user.email)}</p></div></div><div class="account-layout"><div class="account-main">${preferences}${platform.user.role==='admin'?'<section class="card"><p class="eyebrow">ADMIN MASTER</p><h2>Administração da Mentra</h2><p>Gerencie os planos, contas e acessos.</p><a class="primary" href="'+(globalThis.mentraNative?'/admin.html':'/admin')+'">Abrir painel administrativo</a></section>':''}<section class="card account-security"><div class="section-head"><div><span class="eyebrow">ACESSO E PRIVACIDADE</span><h2>Segurança da conta</h2></div></div><details class="account-disclosure"><summary><span>Alterar senha<small>Proteja o acesso à sua conta.</small></span><span aria-hidden="true">＋</span></summary><form id="platform-password" class="form-stack"><label>Senha atual<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>Nova senha<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="form-help">Use de 12 a 128 caracteres. Todos os dispositivos e o WhatsApp vinculado serão desconectados, e seus links privados serão revogados.</p><button class="primary" type="submit">Salvar nova senha e sair</button></form></details><details class="account-disclosure account-danger"><summary><span>Excluir minha conta<small>Exclusão definitiva dos dados da conta.</small></span><span aria-hidden="true">＋</span></summary><p>Esta ação é permanente. Assinaturas ativas precisam ser canceladas antes.</p><form id="platform-delete" class="form-stack"><label>Confirme sua senha<input name="password" type="password" autocomplete="current-password" required></label><label class="check-field"><input type="checkbox" name="confirmed" required><span>Entendo que todos os meus dados serão excluídos.</span></label><button class="outline danger" type="submit">Excluir conta permanentemente</button></form></details><p id="account-error" role="alert" class="form-error"></p></section></div><aside class="account-aside"><section class="card"><span class="eyebrow">SUA ASSINATURA</span><h2>${esc(platform.plans?.find(p=>p.id===platform.subscription.plan)?.name||platform.subscription.plan)}</h2><p>${esc(subscriptionLabel(platform.subscription.status))}</p><a class="outline full" href="#/planos">Ver meus planos</a></section><section class="card account-backup"><span class="eyebrow">CONTROLE DOS SEUS DADOS</span><h2>Sua cópia, com você</h2><p>Baixe uma cópia da sua organização para restaurar ou exporte todos os dados da conta.</p><button class="primary full" data-account="backup">Baixar cópia para restauração</button><button class="outline full" data-account="export">Exportar meus dados</button><p class="form-help">A exportação completa inclui o histórico das integrações. A cópia para restauração contém somente sua organização e seus originais.</p><details class="account-disclosure"><summary><span>Restaurar uma cópia</span><span aria-hidden="true">＋</span></summary><label class="restore-upload">Selecionar arquivo JSON<input type="file" data-restore accept=".json,application/json"></label><p class="form-help">Você verá as diferenças antes de confirmar. Assinatura e credenciais não são restauradas.</p></details></section></aside></div>`;}
// App Store 3.1.1 / Google Play payments: native builds never show or start an external checkout.
const storeApp=()=>Boolean(globalThis.mentraNative);
export function plansMarkup(subscription,plans=[],usage={},paymentsConfigured=false){if(storeApp())return storePlansMarkup(subscription,plans,usage);const current=plans.find(p=>p.id===subscription.plan),active=subscription.status==='active',granted=active&&!subscription.current_period_end;
 // Paying while active adds the period's days to the current end date (early renewal loses nothing).
 const canPay=p=>paymentsConfigured&&Boolean(planCharge(p))&&!granted;
 const label=p=>canPay(p)?`${active?'Renovar':'Pagar'} com PIX · ${brl(planCharge(p))}`:p.id===subscription.plan?'Plano selecionado':active?'Acesso já liberado':'Selecionar';
 const disabled=p=>paymentsConfigured?!canPay(p):active;
 return `<div class="page-heading"><div><p class="eyebrow">ASSINATURA</p><h1>Seu plano, no seu ritmo.</h1><p>${esc(current?.name||subscription.plan)} · ${esc(subscriptionLabel(subscription.status))}${active&&subscription.current_period_end?` · acesso até ${new Date(subscription.current_period_end).toLocaleDateString('pt-BR')}`:''}</p>${usage.month?`<p>${Number(usage.requests||0).toLocaleString('pt-BR')} de ${Number(current?.monthlyRequests||0).toLocaleString('pt-BR')} mensagens usadas em ${esc(usage.month)}. O ciclo de uso segue o mês em UTC.</p>`:''}</div></div><div class="portal-plans">${plans.map(p=>`<section class="card ${p.id===subscription.plan?'plan-selected':''}"><h2>${esc(p.name)}</h2>${planPriceMarkup(p)}<p>${esc(p.description)}</p>${p.days?`<p class="plan-days">Cada pagamento libera ${p.days} dias de acesso.</p>`:''}<p>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA/mês</p><button class="${p.id===subscription.plan?'outline':'primary'}" aria-pressed="${p.id===subscription.plan}" data-platform-plan="${p.id}" ${disabled(p)?'disabled':''}>${label(p)}</button></section>`).join('')}</div>${finePrint(plans)}<p class="notice">${paymentsConfigured?`Pagamento via PIX. O pagamento confirmado libera os dias do período escolhido${active&&!granted?', somados ao fim do seu acesso atual':''}. A renovação é manual.`:'Os pagamentos serão disponibilizados após a configuração do gateway. Selecionar um plano não gera cobrança nem ativa uma assinatura.'}</p><p id="payment-error" class="form-error" role="alert"></p>${paymentsConfigured?'<section id="payment-pix" class="card pix-panel" aria-live="polite" hidden></section>':''}`;}
function storePlansMarkup(subscription,plans,usage){const current=plans.find(p=>p.id===subscription.plan);return `<div class="page-heading"><div><p class="eyebrow">ASSINATURA</p><h1>Seu plano, no seu ritmo.</h1><p>${esc(current?.name||subscription.plan)} · ${esc(subscriptionLabel(subscription.status))}</p>${usage.month?`<p>${Number(usage.requests||0).toLocaleString('pt-BR')} de ${Number(current?.monthlyRequests||0).toLocaleString('pt-BR')} mensagens usadas em ${esc(usage.month)}.</p>`:''}</div></div><div class="portal-plans">${plans.map(p=>`<section class="card ${p.id===subscription.plan?'plan-selected':''}" data-store-plan="${esc(p.id)}"><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p>${p.days?`<p>${p.days} dias de acesso completo</p>`:''}<p>${p.monthlyRequests.toLocaleString('pt-BR')} mensagens de IA/mês</p>${p.id===subscription.plan?'<p class="eyebrow">SEU PLANO</p>':''}</section>`).join('')}</div><p class="notice">A assinatura não é contratada pelo aplicativo. Quando ela está ativa na sua conta Mentra, todos os recursos do plano ficam disponíveis aqui automaticamente.</p>`;}
